{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "waivers.schema.json",
  "title": "Data protection waivers",
  "description": "Approved, dated exceptions for personal data (Restricted level) in specific paths. Lives in the engine folder as waivers.json; the person owns it. Secrets and credentials (Critical level) never have a waiver.",
  "type": "object",
  "required": ["waivers"],
  "additionalProperties": false,
  "properties": {
    "schema": {"type": "integer", "minimum": 1},
    "waivers": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["detector", "path", "reason", "approved_by", "expires"],
        "additionalProperties": false,
        "properties": {
          "detector": {"enum": ["card", "iban", "email", "phone", "ar-cuit", "ar-dni", "br-cpf", "es-nif", "us-ssn"]},
          "path": {"description": "Glob relative to the project root, for example tests/fixtures/**", "type": "string", "minLength": 1},
          "reason": {"type": "string", "minLength": 1},
          "approved_by": {"description": "Who approved it (the tech_lead role).", "type": "string", "minLength": 1},
          "expires": {"description": "Last day the waiver applies, YYYY-MM-DD.", "type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}
        }
      }
    }
  }
}
